export default function SuccessToast({
  message = 'تم إنشاء الحساب وارسال البيانات للمستخدم بنجاح.',
  isOpen,
  onClose,
  duration = 4000,
}: SuccessToastProps) {
  useEffect(() => {
    if (!isOpen) return
    const timer = setTimeout(() => {
      onClose()
    }, duration)
    return () => clearTimeout(timer)
  }, [isOpen, onClose, duration])

  if (!isOpen) return null

  return (
    <div
      className="fixed top-6 left-1/2 -translate-x-1/2 z-50 bg-white border border-[#15A72B] rounded-lg px-4 py-2.5 shadow-[0px_2px_1px_rgba(33,37,41,0.06),0px_0px_1px_rgba(33,37,41,0.08)] flex items-center gap-2.5 font-['Cairo'] text-right select-none animate-in fade-in slide-in-from-top-2 duration-200"
      dir="rtl"
      data-node-id="5634:69914"
      data-name="update ad success mess"
      role="status"
      aria-live="polite"
    >
      <SuccessBadgeIcon className="size-6 shrink-0" />
      <p
        className="text-[16px] font-normal text-[#111111] leading-normal whitespace-nowrap"
        data-node-id="5634:69922"
      >
        {message}
      </p>
    </div>
  )
}
